begin;

-- BXH HLV "Đập +8 nhiều nhất" (2026-11-14, người dùng): đếm số cầu thủ KHÁC NHAU mà HLV đập thành công lên +8, mỗi mùa tính tối đa
-- 3 cầu thủ. Thẻ có sẵn +8 (gói / mua chợ) không tính; tính từ khi chạy migration (máy chủ chưa lưu lịch sử đập trước đó).
--   fco_plus8(user_id, player_id, at): ghi trong fco_stp_mission_upgrade (được fco_inv_upgrade gọi mỗi lần đập thành công).
--   fco_player_tiers(player_id, tier): mùa của từng cầu thủ (máy chủ không có cột mùa). MÙA MỚI PHẢI THÊM DÒNG (migration mới);
--   cầu thủ chưa có mùa thì tính như một mùa riêng của chính nó.
--   fco_plus8_board(): top 10 + hạng của mình. Bằng điểm thì ai đạt điểm đó trước xếp trên. Chạy lại được.

create table if not exists public.fco_player_tiers (player_id integer primary key, tier text not null);
alter table public.fco_player_tiers enable row level security;
revoke all on public.fco_player_tiers from anon, authenticated;
on conflict (player_id) do update set tier = excluded.tier;

create table if not exists public.fco_plus8 (
  user_id uuid not null references auth.users(id) on delete cascade,
  player_id integer not null,
  at timestamptz not null default now(),
  primary key (user_id, player_id)
);
alter table public.fco_plus8 enable row level security;
revoke all on public.fco_plus8 from anon, authenticated;

-- Như 202611120008, thêm ghi +8.
create or replace function public.fco_stp_mission_upgrade(p_uid uuid, p_player integer, p_level integer) returns void
language plpgsql volatile security definer set search_path = '' as $$
declare ovr integer := public.fco_inv_ovr(p_player, p_level);
begin
  select p_uid, public.fco_today(), d.id from public.fco_stp_mission_defs d
  where d.kind = 'upgrade' and p_level >= d.level and public.fco_inv_name(p_player) = any(d.names)
  on conflict do nothing;
  -- BXH "Đập +8 nhiều nhất" (202611140005): đập thành công lên đúng +8 → ghi cầu thủ (mỗi cầu thủ một lần / HLV).
  if p_level = 8 then
  end if;
  if ovr > public.fco_live_min_ovr() then
    perform public.fco_live_post(p_uid, 'upgrade', '🔥 Chúc mừng HLV ' || public.fco_public_name(p_uid) || ' đập thành công ' || public.fco_inv_name(p_player)
      || ' lên +' || p_level || ' · OVR ' || ovr || '!');
  end if;
end;
$$;

-- Điểm từng HLV: mỗi mùa tối đa 3 cầu thủ (3 cầu thủ đạt +8 sớm nhất của mùa đó); 'at' = lúc đạt cầu thủ được tính cuối cùng.
create or replace function public.fco_plus8_scores() returns table (user_id uuid, score bigint, reached timestamptz)
language sql stable security definer set search_path = '' as $$
  select user_id, count(*), max(at) from (
    select p.user_id, p.at, row_number() over (partition by p.user_id, coalesce(t.tier, 'id:' || p.player_id) order by p.at, p.player_id) as k
      from public.fco_plus8 p left join public.fco_player_tiers t on t.player_id = p.player_id) x
  where k <= 3 group by user_id
$$;
revoke all on function public.fco_plus8_scores() from public, anon, authenticated;

create or replace function public.fco_plus8_board() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare uid uuid := public.fco_require_user(); mine record;
begin
  select s.score, s.reached into mine from public.fco_plus8_scores() s where s.user_id = uid;
  return jsonb_build_object(
    'top', coalesce((select jsonb_agg(jsonb_build_object('name', public.fco_public_name(t.user_id), 'count', t.score, 'mine', t.user_id = uid,
                       'effect', public.fco_name_effect(t.user_id), 'club', public.fco_club_logo(t.user_id)) order by t.score desc, t.reached, t.user_id)
                     from (select * from public.fco_plus8_scores() order by score desc, reached, user_id limit 10) t), '[]'::jsonb),
    'me', jsonb_build_object('count', coalesce(mine.score, 0),
      'rank', case when mine.score is not null then 1 + (select count(*) from public.fco_plus8_scores() o
              where o.score > mine.score or (o.score = mine.score and o.reached < mine.reached)) end));
end;
$$;
revoke all on function public.fco_plus8_board() from public, anon;
grant execute on function public.fco_plus8_board() to authenticated;

commit;
